import subprocess
import time

def wait_for_boot():
    deadline = time.monotonic() + 180
    while time.monotonic() < deadline:
        state = subprocess.run(['adb', '-s', 'emulator-5580', 'get-state'], capture_output=True, text=True, timeout=min(10, max(0.1, deadline-time.monotonic())))
        if state.returncode:
            detail = (state.stdout + state.stderr).strip()
            if 'offline' not in detail and 'not found' not in detail and 'no devices/emulators found' not in detail:
                raise RuntimeError('Assigned device state failed: ' + detail)
        elif state.stdout.strip() == 'device':
            boot = subprocess.run(['adb', '-s', 'emulator-5580', 'shell', 'getprop', 'sys.boot_completed'], capture_output=True, text=True, timeout=min(10, max(0.1, deadline-time.monotonic())))
            if boot.returncode:
                raise RuntimeError('Assigned device boot query failed: ' + (boot.stdout + boot.stderr).strip())
            if boot.stdout.strip() == '1':
                print('Assigned emulator boot completed')
                return
            if boot.stdout.strip() not in ('', '0'):
                raise RuntimeError('Unexpected boot property: ' + repr(boot.stdout))
        elif state.stdout.strip() != 'offline':
            raise RuntimeError('Unexpected device state: ' + repr(state.stdout))
        time.sleep(min(2, max(0, deadline-time.monotonic())))
    raise TimeoutError('Assigned emulator did not boot within 180 seconds')

if __name__ == '__main__':
    wait_for_boot()
